#include <stddef.h>
#include <limits.h>
#include <stdbool.h>

void fill(int *a, size_t n, int v) {
    for (size_t i = 0; i < n; i++) a[i] = v;       /* was i <= n: one past the end. */
}

bool add_checked(int a, int b, int *out) {          /* avoid signed overflow UB. */
    if ((b > 0 && a > INT_MAX - b) || (b < 0 && a < INT_MIN - b)) return false;
    *out = a + b;
    return true;
}
```

