gcc -std=c17 -Wall -Wextra -g -O1 \
    -fsanitize=address,undefined -fno-omit-frame-pointer \
    fill.c test_fill.c -o test_fill
./test_fill
# ERROR: AddressSanitizer: stack-buffer-overflow ... WRITE of size 4
#     #0 fill fill.c:6
